-- M1 buildings: Town Hall (#24), Housing Tent/Cabin (#28), labour huts (each is its own tool store, #31), hidden
-- power sink. Placeholder art: generated 3/4 sprites (scripts/gen_art.py, art_manifest.lua).
local G = "__colony-bio-logistics__/graphics/"
local ART = require("prototypes.art_manifest")
-- Placeholder art lives in mod/graphics (generated by scripts/gen_art.py). `half` = half collision size in tiles.
-- Sprite geometry (source size, scale and the shift that keeps the footprint on the entity box) is emitted by the
-- art generator into art_manifest.lua, so a taller 3/4 building stands up instead of being squashed into its box.
-- The shadow png is twice as wide, same centre (see scripts/artlib.py).
local function sprite(file, extra)
  local m = ART[file]
  assert(m, "missing art manifest entry: " .. file)
  local main = {filename = G .. file .. ".png", width = m.width, height = m.height, scale = m.scale,
                shift = {m.shift[1], m.shift[2]}}
  local shadow = {filename = G .. file .. "-shadow.png", width = m.width * 2, height = m.height, scale = m.scale,
                  shift = {m.shift[1], m.shift[2]}, draw_as_shadow = true}
  for k, v in pairs(extra or {}) do main[k] = v; shadow[k] = v end
  return {layers = {main, shadow}}
end

local function chest_clone(base, name, art, size, half, half_y)
  half_y = half_y or half
  local e = table.deepcopy(data.raw["container"][base])
  e.name = name
  e.minable = {mining_time = 0.5, result = name}
  e.inventory_size = size
  e.localised_name = {"entity-name." .. name}
  e.localised_description = {"entity-description." .. name}
  e.picture = sprite(art)
  e.icon = G .. "icon-" .. art .. ".png"; e.icon_size = 64; e.icons = nil
  e.collision_box = {{-half + 0.1, -half_y + 0.1}, {half - 0.1, half_y - 0.1}}
  e.selection_box = {{-half, -half_y}, {half, half_y}}
  e.circuit_connector = nil
  e.fast_replaceable_group = nil
  e.next_upgrade = nil
  return e
end

local function item_of(entity, art, order)
  return {
    type = "item", name = entity.name, icon = G .. "icon-" .. art .. ".png", icon_size = 64,
    subgroup = "storage", order = order, place_result = entity.name, stack_size = 10,
    localised_name = {"entity-name." .. entity.name},
  }
end

local function recipe(name, ingredients, time, amount, enabled)
  local ing = {}
  for item, n in pairs(ingredients) do ing[#ing + 1] = {type = "item", name = item, amount = n} end
  return {type = "recipe", name = name, enabled = enabled == nil and true or enabled, energy_required = time,
    ingredients = ing, results = {{type = "item", name = name, amount = amount or 1}}}
end

