local function tool(name, icon)
  return {type = "item", name = name, icon = G .. icon, icon_size = 64, subgroup = "tool",
    order = "z[colony]-" .. name, stack_size = 20, localised_name = {"item-name." .. name}}
end

-- Selection tool (#35): drag over machines to opt them into colony supply, alt-drag to opt out.
-- Saves opening every machine's panel just to tick one checkbox.
local marker = {
  type = "selection-tool", name = "colony-logistics-marker",
  icon = G .. "icon-town-hall.png", icon_size = 64,
  localised_name = {"item-name.colony-logistics-marker"},
  localised_description = {"item-description.colony-logistics-marker"},
  subgroup = "tool", order = "z[colony]-g[marker]", stack_size = 1,
  flags = {"not-stackable", "spawnable"},
  select = {mode = {"any-entity"}, cursor_box_type = "entity", border_color = {0.2, 0.9, 0.3}},
  alt_select = {mode = {"any-entity"}, cursor_box_type = "entity", border_color = {0.9, 0.3, 0.2}},
}

-- Native range preview: drawn while the item is held in the cursor and while the entity is selected, so the
-- circle is visible *before* placing and when clicking a built one (the engine scales the sprite to `distance`).
local function ring(entity, distance, colour)
  entity.radius_visualisation_specification = {
    sprite = {filename = G .. "radius-" .. colour .. ".png", size = 512},
    distance = distance,
  }
end
ring(hall, 64, "green")             -- territory.HALL_RADIUS
ring(dome, 64, "green")             -- a dome emits the same territory as a hall (#63)
ring(watchtower, 48, "green")       -- territory.TOWER_RADIUS
ring(forager, 96, "yellow")           -- colony.FORAGE_RADIUS
for _, hut in ipairs{woodcutter, miner, farmhut, huntinglodge, fishingdock, smokehouse, kitchen, toolsmith} do
  ring(hut, 48, "yellow")           -- colony.HUT_RADIUS
end
ring(forester, 20, "yellow")        -- forest.RADIUS: it plants close to home, where the woodcutter can reach
ring(patrol_post, 16, "red")        -- patrol.RANGE: hostile detection while walking the route

